export class DrinkingParserV1  {
  constructor() {
  }
  static tryParseVolume (tok : string) : DrinkVolumeResult  {
    const out : DrinkVolumeResult  = new DrinkVolumeResult();
    const numEnd : number  = V1SharedHelpers.splitNumAndUnit(tok);
    if ( numEnd <= 0 ) {
      return out;
    }
    const numPart : string  = tok.substring(0, numEnd );
    const isDec : boolean  = V1SharedHelpers.isDecimalToken(numPart);
    if ( isDec == false ) {
      return out;
    }
    const unitPart : string  = tok.substring(numEnd, (tok.length) );
    if ( unitPart == "l" ) {
      out.found = true;
      out.volume = numPart;
      out.unit = "l";
      return out;
    }
    if ( unitPart == "dl" ) {
      out.found = true;
      out.volume = numPart;
      out.unit = "dl";
      return out;
    }
    if ( unitPart == "ml" ) {
      out.found = true;
      out.volume = numPart;
      out.unit = "ml";
      return out;
    }
    return out;
  };
  static parse (line : string) : DrinkingNode  {
    const n : DrinkingNode  = new DrinkingNode();
    if ( (line.length) <= 9 ) {
      return n;
    }
    let rest : string  = (line.substring(9, (line.length) )).trim();
    const desc : string  = V1SharedHelpers.extractPipeDescription(rest);
    if ( (desc.length) > 0 ) {
      n.hasDescription = true;
      n.description = desc;
      const barPos : number  = V1SharedHelpers.findToken(rest, "|");
      if ( barPos >= 0 ) {
        rest = (rest.substring(0, barPos )).trim();
      }
    }
    const parts : Array<string>  = rest.split(" ");
    const pLen : number  = parts.length;
    let liquidParts : Array<string> | undefined  = [];
    let i : number  = 0;
    while (i < pLen) {
      const tok : string  = parts[i];
      const vol : DrinkVolumeResult  = DrinkingParserV1.tryParseVolume(tok);
      if ( vol.found ) {
        n.hasVolume = true;
        n.volumeRaw = vol.volume;
        n.volumeUnit = vol.unit;
      } else {
        const scan : NutrientScanResult  = NutrientParserV1.tryParseAt((tok + " "), 0);
        if ( scan.found ) {
          if ( scan.name == "kcal" ) {
            n.hasCalories = true;
            n.caloriesRaw = scan.value;
          } else {
            if ( (scan.name == "prot") || (scan.name == "protein") ) {
              n.hasProtein = true;
              n.proteinRaw = scan.value;
            } else {
              n.hasNutrients = true;
              n.nutrientJsonList.push(NutrientParserV1.nutrientJson(scan.name, scan.value, scan.unit));
            }
          }
        } else {
          liquidParts.push(tok);
        }
      }
      i = i + 1;
    };
    if ( (liquidParts.length) > 0 ) {
      n.hasLiquid = true;
      n.liquid = (liquidParts.join(" ")).trim();
    }
    return n;
  };
}
