export class ExpenseParserV1  {
  constructor() {
  }
  static parseCurrencyAmount (tok : string) : ExpenseAmountResult  {
    const out : ExpenseAmountResult  = new ExpenseAmountResult();
    const sLen : number  = tok.length;
    if ( sLen < 3 ) {
      return out;
    }
    const numEnd : number  = V1SharedHelpers.splitNumAndUnit(tok);
    if ( numEnd <= 0 ) {
      return out;
    }
    const numPart : string  = tok.substring(0, numEnd );
    const isDec : boolean  = V1SharedHelpers.isDecimalToken(numPart);
    if ( isDec == false ) {
      return out;
    }
    const curPart : string  = tok.substring(numEnd, sLen );
    if ( (curPart.length) < 3 ) {
      return out;
    }
    out.found = true;
    out.amount = numPart;
    out.currency = curPart;
    return out;
  };
  static parse (line : string) : ExpenseNode  {
    const n : ExpenseNode  = new ExpenseNode();
    if ( (line.length) <= 8 ) {
      return n;
    }
    const rest : string  = (line.substring(8, (line.length) )).trim();
    const noteSep : number  = V1SharedHelpers.findToken(rest, " | ");
    let core : string  = rest;
    if ( noteSep >= 0 ) {
      core = (rest.substring(0, noteSep )).trim();
      const noteText : string  = (rest.substring((noteSep + 3), (rest.length) )).trim();
      if ( (noteText.length) > 0 ) {
        n.hasDescription = true;
        n.description = noteText;
      }
    }
    if ( V1SharedHelpers.hasPrefix(core, "entry ") ) {
      const afterEntry : string  = (core.substring(6, (core.length) )).trim();
      const parts : Array<string>  = afterEntry.split(" ");
      const pLen : number  = parts.length;
      let nameParts : Array<string> | undefined  = [];
      let i : number  = 0;
      while (i < pLen) {
        const tok : string  = parts[i];
        const amt : ExpenseAmountResult  = ExpenseParserV1.parseCurrencyAmount(tok);
        if ( amt.found ) {
          n.hasNamedEntry = true;
          n.namedEntryName = (nameParts.join(" ")).trim();
          n.amountRaw = amt.amount;
          n.currency = amt.currency;
          let j : number  = i + 1;
          while (j < pLen) {
            const tok2 : string  = parts[j];
            const amt2 : ExpenseAmountResult  = ExpenseParserV1.parseCurrencyAmount(tok2);
            if ( amt2.found ) {
              n.hasVatAmount = true;
              n.vatAmountRaw = amt2.amount;
            } else {
              const isAlv : boolean  = V1SharedHelpers.hasPrefix(tok2, "ALV");
              if ( isAlv ) {
                const pctStart : number  = V1SharedHelpers.findToken(tok2, "%");
                if ( pctStart > 3 ) {
                  const pctStr : string  = tok2.substring(3, pctStart );
                  if ( V1SharedHelpers.isDecimalToken(pctStr) ) {
                    n.hasVatPercent = true;
                    n.vatPercentRaw = pctStr;
                  }
                }
              }
            }
            j = j + 1;
          };
          return n;
        }
        nameParts.push(tok);
        i = i + 1;
      };
      return n;
    }
    const parts_1 : Array<string>  = core.split(" ");
    const pLen_1 : number  = parts_1.length;
    let i_1 : number  = 0;
    while (i_1 < pLen_1) {
      const tok_1 : string  = parts_1[i_1];
      const amt_1 : ExpenseAmountResult  = ExpenseParserV1.parseCurrencyAmount(tok_1);
      if ( amt_1.found ) {
        if ( (n.amountRaw.length) == 0 ) {
          n.amountRaw = amt_1.amount;
          n.currency = amt_1.currency;
        } else {
          n.hasVatAmount = true;
          n.vatAmountRaw = amt_1.amount;
        }
      } else {
        const isAlv_1 : boolean  = V1SharedHelpers.hasPrefix(tok_1, "ALV");
        if ( isAlv_1 ) {
          const pctStart_1 : number  = V1SharedHelpers.findToken(tok_1, "%");
          if ( pctStart_1 > 3 ) {
            const pctStr_1 : string  = tok_1.substring(3, pctStart_1 );
            const isPct : boolean  = V1SharedHelpers.isDecimalToken(pctStr_1);
            if ( isPct ) {
              n.hasVatPercent = true;
              n.vatPercentRaw = pctStr_1;
            }
          }
        }
      }
      i_1 = i_1 + 1;
    };
    return n;
  };
}
export class V1LineParser  {
  constructor() {
  }
  static parse (tag : string, line : string) : AstNode  {
    if ( tag == "pyramid" ) {
      const parsed : PyramidNode  = PyramidParserV1.parse(line);
      if ( (parsed.setJsonList.length) == 0 ) {
        const rest : string  = (line.substring(8, (line.length) )).trim();
        const barPos : number  = V1SharedHelpers.findToken(rest, "|");
        if ( barPos > 0 ) {
          const left : string  = (rest.substring(0, barPos )).trim();
          const right : string  = (rest.substring((barPos + 1), (rest.length) )).trim();
          const moveLine : string  = (("Move " + left) + "x") + right;
          return MoveParserV1.parse(moveLine);
        }
        return MoveParserV1.parse(("Move " + rest));
      }
      return parsed;
    }
    if ( tag == "custom" ) {
      return CustomParserV1.parse(line);
    }
    if ( tag == "food" ) {
      return FoodParserV1.parse(line);
    }
    if ( tag == "drinking" ) {
      return DrinkingParserV1.parse(line);
    }
    if ( tag == "expense" ) {
      return ExpenseParserV1.parse(line);
    }
    const u : UnknownFallbackNode  = new UnknownFallbackNode();
    u.raw = line;
    return u;
  };
}
