        const repsRaw : string  = left.substring((xPos + 1), (left.length) );
        const parsedSets : number  = V1SharedHelpers.parseStrictInt(setsRaw);
        const plusPos : number  = V1SharedHelpers.findToken(repsRaw, "+");
